import{esc,button as b,number as n,input,range,select}from'./ui.js';
const colors=['#b28150','#688f88','#8e84aa','#d4ae54'];
const polar=a=>[130+105*Math.cos((a-90)*Math.PI/180),130+105*Math.sin((a-90)*Math.PI/180)];
const sector=(a,z)=>{if(z-a>=359.99)return 'M130 25A105 105 0 1 1 130 235A105 105 0 1 1 130 25Z';const p=polar(a),q=polar(z);return `M130 130 L${p.join(' ')} A105 105 0 ${z-a>180?1:0} 1 ${q.join(' ')} Z`;};
const round=(den,selected,click=true,action='fraction-cell',row=null)=>`<svg viewBox="0 0 260 260" class="x-round" role="group" aria-label="圆形等份">${Array.from({length:den},(_,i)=>`<path d="${sector(i*360/den,(i+1)*360/den)}" fill="${selected.includes(i)?colors[0]:'#f5f0e3'}" stroke="#fff" stroke-width="2" ${click?`data-x="${action}" data-index="${i}" ${row===null?'':`data-row="${row}"`} tabindex="0" role="button" aria-label="第 ${i+1} 份" aria-pressed="${selected.includes(i)}"`:''}/>`).join('')}</svg>`;
const bar=(den,selected,action='fraction-cell',row=null)=>`<div class="x-strip" style="grid-template-columns:repeat(${den},1fr)">${Array.from({length:den},(_,i)=>b(action,'',`data-index="${i}" ${row===null?'':`data-row="${row}"`} class="${selected.includes(i)?'on':''}" aria-label="${row===null?'':'第 '+(row+1)+' 行，'}第 ${i+1} 份" aria-pressed="${selected.includes(i)}"`)).join('')}</div>`;
const percentGrid=m=>`<div class="hundred">${Array.from({length:100},(_,i)=>b('dec-cell','',`data-index="${i}" class="${m.selected.includes(i)?'on':''}" aria-label="百分格 ${i+1}"`)).join('')}</div>`;
const line=(parts,mark,end=1)=>`<svg class="number-line" viewBox="0 0 600 125" aria-label="数轴"><path d="M30 65H570" stroke="#5b665c" stroke-width="3"/>${Array.from({length:parts+1},(_,i)=>`<path d="M${30+540*i/parts} 55v20" stroke="#5b665c"/><text x="${30+540*i/parts}" y="102" text-anchor="middle">${i===0?'0':i===parts?(end===.1?'1/10':typeof end==='string'?end:'1'):''}</text>`).join('')}<path d="M30 40H${30+540*mark/parts}" stroke="#b28150" stroke-width="5"/><circle cx="${30+540*mark/parts}" cy="65" r="8" fill="#b28150"/></svg>`;
export function visual(t,m){switch(t.type){
case'x-circlecut':{const cuts=[0,...m.cuts.slice().sort((a,b)=>a-b),360];return `<svg viewBox="0 0 260 260" class="x-round">${cuts.slice(1).map((z,i)=>`<path d="${sector(cuts[i],z)}" fill="${colors[i]}" stroke="white" stroke-width="2"/>`).join('')}</svg>`;}
case'x-mosaic':return `<div class="x-mosaic">${m.cells.map((c,i)=>b('paint',c<0?'':String(c+1),`data-index="${i}" style="background:${colors[c]||'#f4efe2'}" aria-label="纸上第 ${i+1} 格"`)).join('')}</div><p>${colors.map((_,i)=>`${i+1} 号：${m.cells.filter(c=>c===i).length} 格`).join('　')} · 已存 ${m.saved.length} 种分法</p>`;
case'x-fraction':return t.shape==='circle'?round(m.den,m.selected):t.shape==='square'?`<div class="x-mosaic" style="grid-template-columns:repeat(${m.den%2?1:2},1fr)">${Array.from({length:m.den},(_,i)=>b('fraction-cell','',`data-index="${i}" class="${m.selected.includes(i)?'on':''}" aria-label="第 ${i+1} 份"`)).join('')}</div>`:`<p>每条纸带是一个整体</p>${Array.from({length:t.n>t.d?2:1},(_,row)=>`<div class="x-strip" style="grid-template-columns:repeat(${m.den},1fr)">${Array.from({length:m.den},(_,i)=>b('fraction-cell','',`data-index="${row*m.den+i}" class="${m.selected.includes(row*m.den+i)?'on':''}" aria-label="第 ${row*m.den+i+1} 小份"`)).join('')}</div>`).join('')}`;
case'x-foldpaper':return `<div class="x-strip" style="grid-template-columns:repeat(${2**m.folds},1fr)">${Array.from({length:2**m.folds},()=>'<span class="fold-piece"></span>').join('')}</div><p>折痕模拟 · 每次把每份一分为二</p>`;
case'x-fgroups':return `<div class="x-token-bank">${m.groups.map((g,i)=>b('group-token','●',`data-index="${i}" style="color:${colors[g]||'#aaa'}" aria-label="珠子 ${i+1}，${g<0?'未分组':'第 '+(g+1)+' 组'}"`)).join('')}</div><div class="x-bowls">${Array.from({length:t.groups},(_,g)=>`<div style="border-color:${colors[g]}"><b>第 ${g+1} 组</b><p>${'● '.repeat(m.groups.filter(v=>v===g).length)}</p>${b('take-group','取这组',`data-index="${g}" aria-pressed="${m.take===g}"`)}</div>`).join('')}</div>`;
case'x-fline':return line(m.parts,m.mark,t.end);
case'x-fwall':return t.denominators.map((d,i)=>`<p>一个整体分 ${d} 份</p>${t.round?round(d,Array.from({length:m.counts[i]},(_,j)=>j),true,'wall-cell',i):bar(d,Array.from({length:m.counts[i]},(_,j)=>j),'wall-cell',i)}`).join('');
case'x-hundredsplit':return `<p>整个纸带</p><div class="x-strip" style="grid-template-columns:repeat(10,1fr)">${Array.from({length:10},(_,i)=>`<span class="fold-piece" style="background:${i===0?colors[0]:'#eee8d8'}"></span>`).join('')}</div><p>放大其中一条</p><div class="x-strip" style="grid-template-columns:repeat(${m.parts},1fr)">${Array.from({length:m.parts},()=>'<span class="fold-piece"></span>').join('')}</div><p>现在数了 ${m.count} 个百分格：${m.visited.join(' → ')}</p>${line(15,m.count,'15/100')}`;
case'x-decvalue':return `<p>${'▣ '.repeat(m.ones)} ${m.ones} 个整份；下面再取小格</p>${percentGrid(m)}<p>取了 ${m.selected.length} 个百分格</p>`;
case'x-scale':{const scale=m.applied?m.n/m.d:1;return `<p>原来长 ${t.base}</p><div class="x-scale-bench"><div class="x-scale-reference" style="width:45%"></div><div class="x-scale-bar" style="width:${Math.min(100,45*scale)}%">${m.applied?(t.base*scale).toFixed(2):t.base}</div></div><p>${m.applied?`按 ${m.n}/${m.d} 改变长度`:'先留下预测，才改变长度'}${45*scale>100?'（超出画框，已截短显示）':''}</p>`;}
case'x-ratio':{const a=m.a*m.value,c=m.b*m.value;return m.view==='bar'?`<p>每一小块 ${m.value} 颗；合计 ${a+c} 颗</p>${[m.a,m.b].map((v,i)=>`<div class="x-strip ratio-strip" style="width:${v*9}%;grid-template-columns:repeat(${v||1},1fr)">${Array.from({length:v},()=>`<span style="background:${colors[i]}">${m.value}</span>`).join('')}</div>`).join('')}`:m.view==='table'?`<table class="x-table"><tr><th>每份颗数</th><th>第一人</th><th>第二人</th></tr>${[1,2,m.value].filter((v,i,a)=>a.indexOf(v)===i).map(v=>`<tr><td>${v}</td><td>${v*m.a}</td><td>${v*m.b}</td></tr>`).join('')}</table>`:`<svg viewBox="0 0 600 180" class="number-line">${[m.a,m.b].map((v,r)=>`<text x="20" y="${25+r*90}">第 ${r+1} 人</text><path d="M30 ${45+r*90}H570" stroke="${colors[r]}"/>${Array.from({length:m.value+1},(_,i)=>`<path d="M${30+540*i/m.value} ${40+r*90}v10" stroke="${colors[r]}"/><text x="${30+540*i/m.value}" y="${70+r*90}" text-anchor="middle">${v*i}</text>`).join('')}`).join('')}</svg>`;}
default:return'';}}
export function controls(t,m){switch(t.type){
case'x-circlecut':return range('cuts.0','第一条分界线',m.cuts[0],1,359)+range('cuts.1','第二条分界线',m.cuts[1],1,359)+n('den','每份是几分之一',m.den);
case'x-mosaic':return `<div class="choice-line">${colors.map((c,i)=>b('paint-color',`${i+1} 号颜色`,`data-index="${i}" style="border-color:${c}" aria-pressed="${m.color===i}"`)).join('')}${b('save-mosaic','保存这次分法')}</div>${n('den','每种颜色占几分之一',m.den)}${input('why','两种形状为什么一样多（可选）',m.why)}`;
case'x-fraction':return `${range('den','一个整体平均分几份',m.den,1,12)}<div class="x-fields">${n('n','取了几份（上面）',m.n)}${n('d','整体分几份（下面）',m.d)}</div>${t.classify?`<div class="x-fields">${select('top','上面的数告诉什么',m.top,[['taken','取了几份'],['whole','整体分几份']])}${select('bottom','下面的数告诉什么',m.bottom,[['taken','取了几份'],['whole','整体分几份']])}</div><p>选所有符合的说法：</p><div class="choice-line">${[['unit','只取一份，且不到整个'],['proper','比整个小'],['improper','达到或超过整个']].map(([v,l])=>b('fraction-class',l,`data-value="${v}" aria-pressed="${m.classes.includes(v)}"`)).join('')}</div>`:''}${t.mixed?`<div class="x-fields">${n('whole','可以换成几个整份',m.whole)}${n('remainder','再加几个四分之一',m.remainder)}</div>`:''}`;
case'x-foldpaper':return `${b('fold-paper','再对折一次',m.folds>=3?'disabled':'')}<div class="x-fields">${m.history.map((_,i)=>n('labels.'+i,`第 ${i+1} 次摊开分成几份`,m.labels[i])).join('')}</div>`;
case'x-fgroups':return `<p>先选一组，再点珠子放进去：</p><div class="choice-line">${Array.from({length:t.groups},(_,i)=>b('group-select','第 '+(i+1)+' 组',`data-index="${i}" aria-pressed="${m.group===i}"`)).join('')}</div>${n('answer','取出一组有几颗',m.answer)}`;
case'x-fline':return `${t.read?'':range('parts','0 到右端分几段',m.parts,1,12)+b('jump','往前走一段')+b('zero','回到零')}<div class="x-fields">${n('unitDen','每一小段是几分之一',m.unitDen)}${n('n','点的名字：几份',m.n)}${n('d','点的名字：几分之',m.d)}</div>`;
case'x-fwall':return `<div class="x-fields">${m.names.map((s,i)=>input('names.'+i,`第 ${i+1} 条涂色的分数`,s,'placeholder="如 1/2" maxlength="40"')).join('')}${select('equal','涂色的量相等吗',m.equal,[['yes','相等'],['no','不相等']])}</div>`;
case'x-hundredsplit':return `${range('parts','一小条再分几份',m.parts,1,10)}${n('den','最小一份是整个的几分之一',m.den)}${b('count-hundred','再数一小格',m.count===12?'disabled':'')}${n('final','最后数到几份百分之一',m.final)}`;
case'x-decvalue':return `${range('ones','整份',m.ones,0,3)}${b('dec-row','再涂 10 格')}<div class="x-fields">${m.digits.map((v,i)=>n('digits.'+i,['个位数字','十分位数字','百分位数字'][i],v)).join('')}${input('decimal','小数写法',m.decimal)}${input('fraction','分数写法',m.fraction,'placeholder="如 1/2"')}${n('percent','百分之几（%）',m.percent)}</div>`;
case'x-scale':return `<div class="x-fields">${range('n','倍数上面的数',m.n,0,12)}${range('d','倍数下面的数',m.d,1,12)}${select('prediction','先预测',m.prediction,[['shorter','变短'],['longer','变长'],['same','不变']])}</div>${b('scale-try','留下预测并试一试')}${select('reason','为什么会这样',m.reason,[['below','倍数比 1 小'],['above','倍数比 1 大'],['one','倍数等于 1']])}`;
case'x-ratio':return `<div class="choice-line">${['a','b'].map((r,i)=>b('ratio-block',`第 ${i+1} 人 ＋ 一块`,`data-row="${r}" data-delta="1"`)+b('ratio-block','− 一块',`data-row="${r}" data-delta="-1"`)).join('')}</div>${range('value','每块几颗',m.value,1,10)}<div class="x-fields">${n('left','第一人分到',m.left)}${n('right','第二人分到',m.right)}</div>${t.compare?`<div class="choice-line">${[['bar','条形'],['table','表格'],['line','双数轴']].map(([v,l])=>b('ratio-view',l,`data-value="${v}" aria-pressed="${m.view===v}"`)).join('')}</div>${select('preferred','要查准确数量，哪种最直接',m.preferred,[['bar','条形'],['table','表格'],['line','双数轴']])}${input('why','另两种画法什么时候方便（可选）',m.why)}`:''}`;
default:return'';}}
export const render=(t,m)=>`<div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}</div>`;
